// Pure, framework-agnostic hostname helpers with ZERO server-only imports —
// split out of lib/hostname.ts so client components (components/nx/order.tsx,
// which pre-fills the VPS checkout hostname field) can import the bits they
// need without pulling in `./db` (a server-only Prisma import that must never
// reach the browser bundle). lib/hostname.ts re-exports everything here, so
// every existing server-side import of "./hostname" keeps working unchanged —
// this file is purely an extraction, not a behavior change.
//
// See lib/hostname.ts's own doc comment for the full "web-01" incident
// background (2026-09-24).

/** Same character rules every checkout flow already validates against
 *  (lib/order.ts orderSchema, lib/game-order.ts HOSTNAME_RE). */
export const HOSTNAME_RE = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i;
export const HOSTNAME_MAX_LEN = 40;

/**
 * Hostnames that must never be handed to (or typed by) a customer, because a
 * fixed piece of internal infrastructure is looked up BY that literal string
 * with no other scoping — see lib/hostname.ts's RESERVED_HOSTNAMES doc
 * comment for the full "freemc-host" story.
 */
export const RESERVED_HOSTNAMES = new Set(["freemc-host"]);

/** Trim + lowercase — the same normalization HostingHostnameClaim's rows use
 *  (normalizeClaimHostname, lib/hosting.ts), so "Web-01" and "web-01" can't
 *  be treated as different names and dodge the unique constraint. */
export function normalizeHostname(raw: string): string {
  return String(raw ?? "").trim().toLowerCase();
}

/** Short base36 suffix — a collision-breaker, not a secret. */
export function randHostnameSuffix(n = 5): string {
  return Math.random().toString(36).slice(2, 2 + n);
}

/**
 * The VPS checkout wizard's pre-filled default (components/nx/order.tsx's
 * `seedOrder`) — a randomized `vps-xxxx`, never the same literal twice.
 *
 * Before this, every VPS checkout that left the field untouched submitted
 * the exact same hardcoded "web-01", and production ended up with 7 unrelated
 * customers all named that (see lib/hostname.ts's doc comment for the
 * resulting cross-customer data-exposure incident). This alone does not
 * guarantee uniqueness — two customers' browsers can still roll the same 4
 * characters in the same instant, however unlikely — so it is only ever a
 * STARTING point: resolveUniqueHostname (server-side, blank-field fallback)
 * and checkHostnameAvailable (lib/actions-hostname-check.ts, the live-typing
 * check) are what actually guard against a collision reaching checkout.
 */
export function genDefaultVpsHostname(): string {
  return `vps-${randHostnameSuffix(4)}`;
}

/** True when a Prisma error is the `Server.hostname` unique-constraint
 *  violation (P2002), as opposed to some other, real failure. */
export function isHostnameConflict(e: unknown): boolean {
  const err = e as { code?: string; meta?: { target?: unknown } } | null | undefined;
  if (err?.code !== "P2002") return false;
  const target = err.meta?.target;
  // Prisma reports the target as either the constraint name or an array of
  // column names, depending on the driver/version — check both shapes.
  if (Array.isArray(target)) return target.includes("hostname");
  return typeof target === "string" && target.includes("hostname");
}

