"use server";

import { requireUser } from "./auth";
import { HOSTNAME_RE, HOSTNAME_MAX_LEN, normalizeHostname } from "./hostname-shared";
import { isHostnameTaken } from "./hostname";

/**
 * Live "is this hostname available" check for the VPS checkout wizard's
 * Hostname field (components/nx/order.tsx / components/nx/DeployView.tsx) —
 * same shape and idiom as checkGameSubdomain (lib/actions-subdomain-check.ts)
 * and checkHostingSubdomain (lib/actions-hosting.ts).
 *
 * Advisory in the sense that the authoritative de-dup is still
 * resolveUniqueHostname's own precheck plus `Server.hostname`'s DB `@unique`
 * constraint (lib/hostname.ts) — a check that says "available" here can still
 * lose a race at submit time and fail cleanly there.
 *
 * UNLIKE the subdomain checks above though (which are advisory-only in the
 * UI and never block Next), this one IS wired to block checkout: see
 * order.tsx's `hostCheck`-gated "configure" step `done` flag and
 * DeployView.tsx's `ready`. That is a deliberate, explicit product decision
 * (owner direction, 2026-09-24, after the "web-01" x7 cross-customer
 * incident — see lib/hostname.ts's doc comment): a customer-typed collision
 * must be surfaced and fixed by the customer, not silently auto-suffixed for
 * them the way resolveUniqueHostname still does for a genuinely blank field.
 */
export async function checkHostnameAvailable(hostnameRaw: string): Promise<{ available: boolean; reason?: string }> {
  await requireUser();
  const hostname = normalizeHostname(hostnameRaw);
  if (!hostname) return { available: false, reason: "Enter a hostname." };
  if (hostname.length < 3) return { available: false, reason: "At least 3 characters." };
  if (hostname.length > HOSTNAME_MAX_LEN) return { available: false, reason: `${HOSTNAME_MAX_LEN} characters or fewer.` };
  if (!HOSTNAME_RE.test(hostname)) return { available: false, reason: "Letters, digits and hyphens only." };
  if (await isHostnameTaken(hostname)) return { available: false, reason: "This hostname is already taken — try another." };
  return { available: true };
}

