/* ── live VPS hostname availability ──────────────────────────────────────
   Same debounce/cancel-guard idiom as gameSubCheck/hostSubCheck
   (components/nx/DeployView.tsx) — 400ms, short enough to feel live, long
   enough that normal typing doesn't fire a round trip per keystroke. Kept
   HERE (in the context) rather than local to the Wizard component like
   those two, because unlike a subdomain check this one has to gate BOTH
   the wizard's own Next button (Wizard, via `sections`'s "configure" done
   flag below) AND the final pay/deploy button (PaymentSlide, a sibling
   component) — both read `useOrder()`, so both see the same result. */
useEffect(() => {
  if (o.service !== "vps") { setHostCheck({ status: "idle" }); return; }
  const h = o.hostname.trim().toLowerCase();
  if (h.length < 3) { setHostCheck({ status: "idle" }); return; }
  setHostCheck({ status: "checking" });
  let cancelled = false;
  const t = setTimeout(async () => {
    try {
      const r = await checkHostnameAvailable(h);
      if (cancelled) return;
      setHostCheck(r.available ? { status: "ok" } : { status: "bad", reason: r.reason });
    } catch {
      if (!cancelled) setHostCheck({ status: "bad", reason: "Couldn't check right now — try again." });
    }
  }, 400);
  return () => { cancelled = true; clearTimeout(t); };
}, [o.service, o.hostname]);

