// One-off local fixture setup for visually verifying the hostname
// pre-fill + live-check UX against an ISOLATED throwaway DB
// (nxeon_hfverify) — never touches real Nxeon infra/data.
import { PrismaClient } from "@prisma/client";

const db = new PrismaClient();

async function main() {
  // A Node row so cat.regions is non-empty (regionsFrom reads from Node
  // rows). Fake Proxmox creds — never actually contacted; only ever hit by
  // real provisioning (worker), which this verification never triggers.
  await db.node.upsert({
    where: { name: "hfverify-node" },
    update: {},
    create: {
      name: "hfverify-node",
      pveNode: "hfverify-pve",
      apiUrl: "https://127.0.0.1:8006",
      tokenId: "fake@pam!fake",
      tokenSecret: "fake-secret",
      publicIp: "127.0.0.1",
      region: "sgp1",
      capacityRamMB: 999999,
      isPrimary: true,
      enabled: true,
      status: "ONLINE",
    },
  });

  const user = await db.user.findUnique({ where: { email: "admin@nxeon.local" } });
  if (!user) throw new Error("admin user missing — run prisma/seed.ts first");

  // Give the test account enough wallet balance to cover a purchase without
  // needing Stripe configured at all.
  await db.walletTransaction.create({
    data: { userId: user.id, amountCents: 100000, description: "hfverify fixture top-up" },
  });

  // A pre-existing Server whose hostname we'll deliberately re-type into the
  // checkout field to trigger the "already taken" live-check path.
  const existing = await db.server.findUnique({ where: { hostname: "taken-test" } });
  if (!existing) {
    const plan = await db.plan.findFirst();
    const os = await db.osTemplate.findFirst();
    if (!plan || !os) throw new Error("plan/osTemplate missing — run prisma/seed.ts first");
    await db.server.create({
      data: {
        name: "taken-test",
        hostname: "taken-test",
        userId: user.id,
        planId: plan.id,
        osTemplateId: os.id,
        status: "RUNNING",
      },
    });
  }

  console.log("Fixtures ready: node=hfverify-node, user=" + user.email + ", collision hostname=taken-test");
}

main().then(() => db.$disconnect()).catch(async (e) => {
  console.error(e);
  await db.$disconnect().catch(() => {});
  process.exit(1);
});

