const SHOT_DIR = "/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/shots";
import { mkdirSync } from "node:fs";
mkdirSync(SHOT_DIR, { recursive: true });

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
const logs = [];
page.on("console", (m) => { if (m.type() === "error") logs.push(m.text()); });

async function shot(name) {
  await page.screenshot({ path: `${SHOT_DIR}/${name}.png` });
  console.log(`  [shot] ${name}`);
}

try {
  console.log("1. Login");
  await page.goto(`${BASE}/login`, { waitUntil: "networkidle" });
  await page.fill('input[name="email"]', "admin@nxeon.local");
  await page.fill('input[name="password"]', "cb03nYIH2UXQmNbu");
  await Promise.all([
    page.waitForNavigation({ waitUntil: "networkidle" }),
    page.click('button[type="submit"]'),
  ]);
  console.log("   -> " + page.url());

  console.log("2. Open deploy wizard, pick VPS");
  await page.goto(`${BASE}/dashboard/deploy`, { waitUntil: "networkidle" });
  await shot("01-deploy-landing");

  // Click the VPS service tile.
  const vpsTile = page.locator("text=VPS Servers").first();
  await vpsTile.click();
  await page.waitForTimeout(500);
  await shot("02-vps-picked");

  console.log("3. Read the pre-filled hostname default");
  const hostInput = page.locator('input[placeholder="vps-4f2a"]');
  await hostInput.waitFor({ state: "visible", timeout: 10000 });
  const defaultVal = await hostInput.inputValue();
  console.log(`   default hostname = "${defaultVal}"`);
  await shot("03-hostname-prefilled");

  console.log("4. Type a hostname that's already taken (taken-test)");
  await hostInput.fill("");
  await hostInput.type("taken-test", { delay: 30 });
  // Debounce is 400ms; wait comfortably past it.
  await page.waitForTimeout(1200);
  await shot("04-hostname-taken-shake");

  const fieldClass = await hostInput.locator("..").getAttribute("class");
  console.log(`   field wrapper class = "${fieldClass}"`);
  const errorText = await page.locator("text=already taken").first().textContent().catch(() => null);
  console.log(`   inline error text = "${errorText}"`);

  console.log("5. Confirm Next is blocked while the bad hostname stands");
  const nextBtn = page.locator('button:has-text("Next")').first();
  await nextBtn.click();
  await page.waitForTimeout(600);
  const urlAfterBlockedNext = page.url();
  await shot("05-next-blocked");
  const stillOnConfigure = await page.locator("text=Choose your plan").count();
  console.log(`   still on Configure step after blocked Next: ${stillOnConfigure > 0}`);

  console.log("6. Fix the hostname to something available");
  await hostInput.fill("");
  await hostInput.type("vps-verify-ok", { delay: 30 });
  await page.waitForTimeout(1200);
  await shot("06-hostname-fixed-ok");
  const okIconVisible = await page.locator(".field .flex-none.text-mint").count();
  console.log(`   "ok" check icon present: ${okIconVisible > 0}`);

  console.log("7. Confirm Next now proceeds");
  await nextBtn.click();
  await page.waitForTimeout(800);
  await shot("07-next-proceeded");
  const stillBlocked = await page.locator("text=Choose your plan").count();
  console.log(`   advanced past Configure: ${stillBlocked === 0 ? "yes" : "no (blocked)"}`);

  console.log("\nConsole errors captured:", logs.length ? logs : "(none)");
} catch (e) {
  console.error("VERIFICATION SCRIPT ERROR:", e);
  await shot("ERROR-state");
  process.exitCode = 1;
} finally {
  await browser.close();
}

