import { PrismaClient } from "@prisma/client";
import bcrypt from "bcryptjs";

const db = new PrismaClient();

input.new_string:
// A plain CUSTOMER account — the admin seed user routes into /admin on
// login (roleHome), not the customer checkout wizard at /dashboard/deploy.
const CUST_EMAIL = "hfverify-customer@nxeon.local";
const CUST_PASSWORD = "hfverify-pw-12345";
let user = await db.user.findUnique({ where: { email: CUST_EMAIL } });
if (!user) {
  user = await db.user.create({
    data: {
      email: CUST_EMAIL,
      name: "HF Verify Customer",
      role: "CUSTOMER",
      emailVerifiedAt: new Date(),
      passwordHash: await bcrypt.hash(CUST_PASSWORD, 12),
    },
  });
} else {
  await db.user.update({ where: { id: user.id }, data: { passwordHash: await bcrypt.hash(CUST_PASSWORD, 12), emailVerifiedAt: new Date() } });
}
console.log(`Customer login: ${CUST_EMAIL} / ${CUST_PASSWORD}`);

