// Dismiss the "Limited time / 7-day free trial" promo modal if it appears —
// click straight through the DOM (bypassing Playwright's actionability/
// overlay checks, which kept tripping on the modal's own internal layers)
// rather than simulating a real pointer click.
const dismissed = await page.evaluate(() => {
  const scrim = document.querySelector(".promo-scrim");
  if (!scrim) return "no-modal";
  const btns = Array.from(scrim.querySelectorAll("button, a"));
  const closeBtn = btns.find((b) => /no thanks/i.test(b.textContent || "")) ||
                    scrim.querySelector('button[aria-label="Close" i]') ||
                    btns[0];
  if (closeBtn) { closeBtn.click(); return "clicked:" + (closeBtn.textContent || "").trim(); }
  return "no-button";
});
console.log(`   promo modal dismissal: ${dismissed}`);
await page.waitForTimeout(400);
await shot("01-deploy-landing");

