function BottomBar({ i, go, onNext, hint, last }: {
  i: number; go: (n: number) => void; onNext: () => void; hint: string | null; last: number;
}) {
  const { o, plan, price, pricing, cat, game } = useOrder();
  const money = useMoney();
  const svc = SERVICE_TILES.find((s) => s.key === o.service);
  const region = cat.regions.find((r) => r.key === o.region);
  const extras = o.addons.length + (o.diskGb ? 1 : 0);
  const term = cat.terms.find((t) => t.months === o.termMonths);
  /* A game order's basket line is the GAME, not the generic service mark: its
     cover art and title, subtitled with the tier the customer picked. `plan` is
     the VPS plan and is null on a game order, so without this the bar read
     "Game Servers" with no indication of which game or which size. */
  const gameTier = game?.tiers.find((t) => t.id === o.gamePlanId) ?? null;

  /* What the customer has actually chosen, PER PRODUCT.
   *
   * This whole block used to be gated on `plan` alone — the VPS plan — which is
   * null on every other product. So a game, hosting, email or domain order sat
   * here reading "Nothing selected yet / Pick a service to start" while the very
   * same bar displayed a real total the customer was about to be charged. The
   * summary now names whichever thing the current product selects.
   *
   * Domains renew per REGISTRATION YEAR, not on the commitment ladder, so they
   * get their own renewal wording rather than a months figure. */
  const picked =
      o.service === "game"     ? (gameTier ? `${game?.name ?? "Game"} · ${gameTier.name}` : null)
    : o.service === "hosting"  ? cat.hosting.find((h) => h.id === o.hostingPlanId)?.name ?? null
    : o.service === "email"    ? cat.email.find((e) => e.id === o.emailPlanId)?.name ?? null
    : o.service === "domains"  ? (o.domainName || null)
    : plan?.name ?? null;

  /* True while a Minecraft order has a tier but no play address yet — the one
     case where the total legitimately has nothing to show. */
  const needsPlayAddress =
    o.service === "game" && !!game?.needsSubdomain && o.subdomain.trim().length <= 2;

  const renews =
      o.service === "domains"
        ? `Renews every ${o.years === 1 ? "year" : `${o.years} years`}`
        : `Renews ${o.termMonths === 1 ? "monthly" : `every ${o.termMonths} months`}`;

  return (
    /* The right inset clears the live-chat bubble, which is `fixed bottom-4
       right-4 z-[60]` — without it the bubble sits on top of Next, the one
       control that moves the wizard forward. */
    <div className="fixed inset-x-0 bottom-[68px] z-30 px-3.5 sm:px-5 lg:bottom-4 lg:left-[76px] lg:pl-6 lg:pr-[92px] xl:left-[248px]">
      {/* A dark island: this bar is 94%-opaque dark navy by design regardless
          of theme, and its service-name label used the bare `text-white`
          utility, which the light theme now resolves to near-black ink —
          invisible on a bar this dark. Same class of bug as the two hero
          fixes above; the island re-themes every token inside at once. */}
      <div className="nx-dark-island mx-auto flex max-w-[1340px] items-center gap-3 rounded-[16px] border border-rim-hi
                      bg-[rgba(1,15,34,0.94)] px-3.5 py-3 shadow-[0_8px_30px_-12px_rgba(0,4,14,0.9)] backdrop-blur">
        <button onClick={() => go(i - 1)} disabled={i === 0}
                className="btn-ghost h-[42px] flex-none px-4 text-[13px] disabled:opacity-40">
          {i === 0 ? "Cancel" : "Back"}
        </button>

        {svc && (
          <div className="hidden min-w-0 items-center gap-2.5 md:flex">
            {game?.art ? (

            {price ? money(price.totalCents) : "—"}
          </span>
        </div>

        {/* Why Next did nothing, said next to the button that did nothing. */}
        {hint && (
          <span className="hidden max-w-[220px] flex-none text-right text-[11px] leading-[1.35] text-rose sm:block">
            {hint}
          </span>
        )}
        {/* NOT `go(i + 1)`: the wizard decides whether the step may be left. */}
        <button onClick={onNext} disabled={!o.service || i >= last}
                className="btn h-[42px] min-w-[104px] flex-none text-[13.5px] disabled:opacity-40">
          Next <span className="arw" aria-hidden>→</span>
        </button>
      </div>
    </div>
  );
}

