/* Both configure folds share one open state — see the note on <Fold>. */
const [foldsOpen, setFoldsOpen] = useState(false);
/* The Hostname field lives inside "Server settings", collapsed by default.
   A customer who opens it, types a taken name, then collapses it again
   (or who never opened it at all and somehow still ends up with a bad
   value — e.g. a stale draft) would otherwise see "Fill in the highlighted
   fields to continue" on Next with nothing actually visible to fix: the
   live-checked `.field-bad` is offscreen inside the closed fold, so
   tryNext's own scroll-to-the-bad-field can't find it either. Force the
   fold back open the moment the live check confirms a collision, so the
   blocking error is never hidden from the very customer it's blocking. */
useEffect(() => {
  if (hostCheck.status === "bad") setFoldsOpen(true);
}, [hostCheck.status]);
const go = (n: number) => setI(Math.max(0, Math.min(sections.length - 1, n)));

